#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Projection/Completion/YAKSys_Hybrid_CPU.Core.CompletionProjectionService.h"
#include "CloseToHSL/Core/Runtime/Completion/Records/TrapCompletionPublicationFence.h"
#include "CloseToHSL/Core/Virtualization/Compatibility/FrozenAbi/VmcsFieldAliases/VmxExitQualification.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ VmxExitQualification q(0x1234,VmxInvalidationScope::AllContexts,0x123456789ULL); assert(q.Encode()==0x2345678900021234ULL); auto completion=std::make_shared<CompletionRecord>(CompletionRecordClass::CompatibilityExit,48,5,6,7); auto allowed=std::make_shared<TrapCompletionPublicationFenceResult>(TrapCompletionPublicationDecision::Allowed,nullptr,completion,true,L""); assert(allowed->CompletionPublicationAllowed && allowed->RetirePublicationAllowed); auto split=std::make_shared<TrapCompletionPublicationFenceResult>(TrapCompletionPublicationDecision::CompletionPublishedRetireDenied,nullptr,completion,false,L""); assert(split->IsCompletionOnly && split->IsRetireDenied); CompletionProjectionService p; auto projected=p.ProjectToVmx(completion); assert(projected->ExitReason==VmExitReason::EptViolation && projected->ExitQualification==5 && projected->GuestPhysicalAddress==6); auto unknown=std::make_shared<CompletionRecord>(CompletionRecordClass::CompatibilityExit,8,0,0,0); assert(p.ProjectReason(unknown)==VmExitReason::SecurityPolicyViolation); assert(p.ProjectToVmx(nullptr)->ExitReason==VmExitReason::None); }
